from pathlib import Path
import re

p=Path('haojing-customer-v20/app/src/main/java/com/haojing/app/MainActivity.java')
s=p.read_text()

s=s.replace(
'hao_app_full_snapshot_v14?select=publish_date,match_no,league,home_team,away_team,kickoff_bjt,eval_status,result_text&order=publish_date.desc,match_no.asc&limit=500',
'hao_app_full_snapshot_v14?select=publish_date,match_no,league,home_team,away_team,kickoff_bjt,unbeaten_pick,cover_text,eval_status,result_text&order=publish_date.desc,match_no.asc&limit=500')

def repl(start,end,body):
    global s
    pat=re.escape(start)+r'.*?(?='+re.escape(end)+r')'
    ns,n=re.subn(pat,lambda m: body+'\n ',s,flags=re.S)
    if n!=1: raise SystemExit(f'patch failed {start} n={n}')
    s=ns

