repl('void drawDates(){','void home(){',r'''void drawDates(){dates.removeAllViews();boolean show=page.equals("home")||page.equals("full")||page.equals("picks");dates.setVisibility(show?View.VISIBLE:View.GONE);if(!show)return;JSONArray src=page.equals("picks")?picks:full;LinkedHashSet<String> ds=new LinkedHashSet<>();for(int i=0;i<src.length();i++){JSONObject o=src.optJSONObject(i);if(page.equals("picks")&&!allowedPick(o))continue;String d=o.optString("publish_date");if(!d.isEmpty())ds.add(d);}if(day.isEmpty()&&!ds.isEmpty())day=ds.iterator().next();for(String d:ds){TextView t=tv(d.length()>=10?d.substring(5).replace("-","/"):d,13,d.equals(day)?Color.WHITE:dark,true);t.setGravity(Gravity.CENTER);t.setBackground(box(d.equals(day)?orange:Color.WHITE,14));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(dp(64),dp(36));lp.setMargins(dp(3),0,dp(3),0);t.setLayoutParams(lp);t.setOnClickListener(v->{day=d;render();});dates.addView(t);}}''')
repl('void home(){','LinearLayout homeCard(JSONObject o){',r'''void home(){String d=day.isEmpty()?latestDate():day;int total=0,settled=0,hit=0,featured=0,warns=0;HashSet<String> fs=new HashSet<>();for(int i=0;i<full.length();i++){JSONObject o=full.optJSONObject(i);if(!d.equals(o.optString("publish_date")))continue;total++;String e=o.optString("eval_status");if(e.contains("成功")){settled++;hit++;}else if(e.contains("失败")||e.contains("未中"))settled++;if(isRiskMatch(d,o.optString("match_no")))warns++;}for(int i=0;i<picks.length();i++){JSONObject q=picks.optJSONObject(i);if(d.equals(q.optString("publish_date"))&&allowedPick(q)&&"正式前瞻".equals(q.optString("record_kind")))fs.add(fmtNo(q.optString("match_no")));}featured=fs.size();LinearLayout hero=card();hero.setBackground(box(dark,20));hero.addView(tv("豪竞2.7",25,Color.WHITE,true));hero.addView(tv("今天只给你两个答案：全池怎么防，精选怎么买",12,0xFFD7D7D7,false));LinearLayout nums=new LinearLayout(this);nums.setPadding(0,dp(14),0,dp(4));TextView a=tv("全池双选\\n"+total+"场",14,gold,true);a.setGravity(Gravity.CENTER);TextView b=tv("正式精选\\n"+featured+"场",14,gold,true);b.setGravity(Gravity.CENTER);TextView c=tv("风险预警\\n"+warns+"场",14,gold,true);c.setGravity(Gravity.CENTER);nums.addView(a,new LinearLayout.LayoutParams(0,-2,1));nums.addView(b,new LinearLayout.LayoutParams(0,-2,1));nums.addView(c,new LinearLayout.LayoutParams(0,-2,1));hero.addView(nums);body.addView(hero);LinearLayout actions=card();actions.setOrientation(LinearLayout.HORIZONTAL);TextView f=tv("查看全池双选",15,Color.WHITE,true);f.setGravity(Gravity.CENTER);f.setBackground(box(orange,14));f.setOnClickListener(v->{page="full";render();});TextView p=tv("查看今日精选",15,dark,true);p.setGravity(Gravity.CENTER);p.setBackground(box(0xFFFFEAD0,14));p.setOnClickListener(v->{page="picks";render();});LinearLayout.LayoutParams lp1=new LinearLayout.LayoutParams(0,dp(46),1);lp1.setMargins(dp(3),0,dp(5),0);LinearLayout.LayoutParams lp2=new LinearLayout.LayoutParams(0,dp(46),1);lp2.setMargins(dp(5),0,dp(3),0);actions.addView(f,lp1);actions.addView(p,lp2);body.addView(actions);LinearLayout performance=card();performance.addView(tv("今日全池评测",18,dark,true));performance.addView(tv(settled==0?"待赛中":hit+" / "+settled+"  ·  "+String.format(Locale.CHINA,"%.1f%%",100.0*hit/settled),22,settled>0&&hit*1.0/settled>=0.75?green:orange,true));performance.addView(tv("口径：每场只评主队不败 / 客队不败，属于双结果覆盖评测。",11,muted,false));body.addView(performance);LinearLayout pickHead=card();pickHead.addView(tv("今日精选",19,dark,true));pickHead.addView(tv("只保留 胜平负 / 让球胜平负；半全场已退出客户精选。",12,muted,false));body.addView(pickHead);LinkedHashSet<String> shown=new LinkedHashSet<>();for(int i=0;i<picks.length();i++){JSONObject q=picks.optJSONObject(i);if(!d.equals(q.optString("publish_date"))||!allowedPick(q)||!"正式前瞻".equals(q.optString("record_kind")))continue;String no=q.optString("match_no");String key=fmtNo(no);if(shown.contains(key))continue;shown.add(key);body.addView(compactPickCard(d,no));if(shown.size()>=3)break;}if(shown.isEmpty()){LinearLayout e=card();e.addView(tv("今天暂无正式精选",17,dark,true));e.addView(tv("达不到门槛就不推，避免把全池硬塞成精选。",12,muted,false));body.addView(e);}}''')
repl('void fullPage(){','void picksPage(){',r'''void fullPage(){LinearLayout h=card();h.addView(tv("全池双选",22,dark,true));h.addView(tv("每场只给一个不败方向 · 主胜+平 / 平+客胜",12,muted,false));body.addView(h);int shown=0;for(int i=0;i<full.length();i++){JSONObject o=full.optJSONObject(i);if(!day.equals(o.optString("publish_date")))continue;LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.addView(tv(fmtNo(o.optString("match_no"))+"  "+o.optString("league"),12,muted,true),new LinearLayout.LayoutParams(0,-2,1));String ev=o.optString("eval_status");if(!ev.isEmpty())top.addView(tv(ev,11,ev.contains("成功")?green:ev.contains("失败")?red:orange,true));c.addView(top);c.addView(tv(o.optString("home_team")+"  VS  "+o.optString("away_team"),17,dark,true));String up=o.optString("unbeaten_pick");if(up.isEmpty())up=o.optString("cover_text").contains("客胜")?"客队不败":"主队不败";TextView dir=tv(up,20,orange,true);dir.setPadding(dp(4),dp(9),dp(4),dp(3));c.addView(dir);String cover=o.optString("cover_text");if(!cover.isEmpty())c.addView(tv("覆盖："+cover,12,muted,false));String rs=o.optString("result_text");c.addView(tv(rs.isEmpty()?"待赛":"赛果  "+rs,12,muted,false));body.addView(c);shown++;}if(shown==0){LinearLayout e=card();e.addView(tv("该日期暂无全池数据",17,dark,true));body.addView(e);}}''')
repl('void picksPage(){','String featuredStatus(ArrayList<JSONObject>a){',r'''void picksPage(){LinearLayout head=card();head.addView(tv("精选推荐",22,dark,true));head.addView(tv("只做两种玩法：胜平负 / 让球胜平负",12,muted,false));head.addView(tv("半全场不再进入精选，也不进入精选命中率。",11,0xFFB46A16,true));body.addView(head);LinkedHashMap<String,ArrayList<JSONObject>> groups=new LinkedHashMap<>();for(int i=0;i<picks.length();i++){JSONObject o=picks.optJSONObject(i);if(!day.equals(o.optString("publish_date"))||!allowedPick(o))continue;String k=fmtNo(o.optString("match_no"));groups.computeIfAbsent(k,x->new ArrayList<>()).add(o);}if(groups.isEmpty()){LinearLayout c=card();c.addView(tv("该日期暂无精选",18,dark,true));c.addView(tv("没有达到门槛的比赛就 PASS。",13,muted,false));body.addView(c);return;}for(Map.Entry<String,ArrayList<JSONObject>> e:groups.entrySet()){ArrayList<JSONObject>a=e.getValue();a.sort((x,y)->Integer.compare(x.optInt("recommendation_rank",99),y.optInt("recommendation_rank",99)));JSONObject f=a.get(0);LinearLayout c=card();LinearLayout top=new LinearLayout(this);top.addView(tv(e.getKey()+"  "+f.optString("league"),12,muted,true),new LinearLayout.LayoutParams(0,-2,1));String rk=f.optString("record_kind");TextView badge=tv(rk.equals("历史回放")?"历史回放":"正式前瞻",11,rk.equals("历史回放")?muted:Color.WHITE,true);if(!rk.equals("历史回放"))badge.setBackground(box(orange,9));badge.setPadding(dp(7),dp(2),dp(7),dp(2));top.addView(badge);c.addView(top);c.addView(tv(f.optString("home_team")+"  VS  "+f.optString("away_team"),17,dark,true));int max=Math.min(2,a.size());for(int j=0;j<max;j++){JSONObject q=a.get(j);String price=q.optString("selected_price");c.addView(tv(catName(q.optString("category"))+"  "+q.optString("selected_pick")+(price.isEmpty()?"":"  SP "+price),16,j==0?0xFFD9362B:orange,true));}String st=featuredStatus(a);c.addView(tv(st,13,st.contains("成功")?green:st.contains("未中")?red:muted,true));body.addView(c);}}''')
repl('void recordPage(){','int[] stat(ArrayList<JSONObject>a,int days){',r'''void recordPage(){int fullN=0,fullHit=0;for(int i=0;i<full.length();i++){JSONObject o=full.optJSONObject(i);String e=o.optString("eval_status");if(e.contains("成功")){fullN++;fullHit++;}else if(e.contains("失败")||e.contains("未中"))fullN++;}LinearLayout a=card();a.addView(tv("全池双选战绩",21,dark,true));a.addView(tv(fullN==0?"暂无已结算样本":fullHit+" / "+fullN+"  ·  "+String.format(Locale.CHINA,"%.2f%%",100.0*fullHit/fullN),25,green,true));a.addView(tv("统计主队不败 / 客队不败双结果覆盖，不等同于单一投注命中率。",11,muted,false));body.addView(a);LinkedHashMap<String,ArrayList<JSONObject>> formal=new LinkedHashMap<>(),hist=new LinkedHashMap<>();for(int i=0;i<picks.length();i++){JSONObject q=picks.optJSONObject(i);if(!allowedPick(q))continue;String ss=q.optString("settle_status");if(!(ss.equals("命中")||ss.equals("未中")||ss.contains("成功")||ss.contains("失败")))continue;String k=q.optString("publish_date")+"|"+fmtNo(q.optString("match_no"));("正式前瞻".equals(q.optString("record_kind"))?formal:hist).computeIfAbsent(k,x->new ArrayList<>()).add(q);}int[] fs=groupStat(formal),hs=groupStat(hist);LinearLayout b=card();b.addView(tv("精选战绩",21,dark,true));b.addView(tv("正式前瞻  "+fmtStat(fs),17,orange,true));b.addView(tv("历史回放  "+fmtStat(hs),14,muted,true));b.addView(tv("精选仅统计胜平负 / 让球胜平负；历史回放与正式发布分开。",11,muted,false));body.addView(b);LinearLayout c=card();c.addView(tv("统计口径",17,dark,true));c.addView(tv("全池：双选覆盖评测\\n精选：胜平负 / 让球胜平负\\n半全场：不展示、不统计",13,muted,false));body.addView(c);}''')
helpers=r'''
 boolean allowedPick(JSONObject q){String c=q.optString("category");return c.equals("胜平负")||c.equals("FT_HAD")||c.equals("让球胜平负")||c.equals("OFFICIAL_HHAD");}
 ArrayList<JSONObject> customerPickList(String d,String n){ArrayList<JSONObject> out=new ArrayList<>();String key=fmtNo(n);for(int i=0;i<picks.length();i++){JSONObject q=picks.optJSONObject(i);if(d.equals(q.optString("publish_date"))&&key.equals(fmtNo(q.optString("match_no")))&&allowedPick(q))out.add(q);}out.sort((x,y)->Integer.compare(x.optInt("recommendation_rank",99),y.optInt("recommendation_rank",99)));return out;}
 LinearLayout compactPickCard(String d,String n){ArrayList<JSONObject>a=customerPickList(d,n);LinearLayout c=card();if(a.isEmpty())return c;JSONObject f=a.get(0);c.addView(tv(fmtNo(n)+"  "+f.optString("league"),12,muted,true));c.addView(tv(f.optString("home_team")+"  VS  "+f.optString("away_team"),16,dark,true));int max=Math.min(2,a.size());for(int i=0;i<max;i++){JSONObject q=a.get(i);c.addView(tv(catName(q.optString("category"))+"  "+q.optString("selected_pick"),15,i==0?0xFFD9362B:orange,true));}return c;}
 int[] groupStat(LinkedHashMap<String,ArrayList<JSONObject>> g){int n=0,h=0;for(ArrayList<JSONObject>a:g.values()){n++;if(featuredStatus(a).contains("成功"))h++;}return new int[]{h,n};}
'''
idx=s.find(' int[] stat(ArrayList<JSONObject>a,int days){')
if idx<0: raise SystemExit('stat not found')
s=s[:idx]+helpers+s[idx:]
s=re.sub(r' boolean isFormalFeatured\(String d,String n\)\{.*?\}', ' boolean isFormalFeatured(String d,String n){ArrayList<JSONObject>a=customerPickList(d,n);for(JSONObject q:a)if("正式前瞻".equals(q.optString("record_kind")))return true;return false;}', s, count=1, flags=re.S)
